    56  static void
    57  exif_mnote_data_apple_load(ExifMnoteData *md, const unsigned char *buf, unsigned int buf_size) {
    58      ExifMnoteDataApple *d = (ExifMnoteDataApple *) md;
    59      unsigned int tcount, i;
    60      unsigned int dsize;
    61      unsigned int ofs, dofs;
    62
    63      /*printf("%s\n", __FUNCTION__);*/
    64
    65      if (!d || !buf || (buf_size < 6 + 16)) {
    66          exif_log(md->log, EXIF_LOG_CODE_CORRUPT_DATA,
    67                   "ExifMnoteDataApple", "Short MakerNote");
    68          return;
    69      }
    70
    71      /* Start of interesting data */
    72      ofs = d->offset + 6;
    73
    74      if ((buf[ofs + 12] == 'M') && (buf[ofs + 13] == 'M')) {
    75          d->order = EXIF_BYTE_ORDER_MOTOROLA;
    76      } else if ((buf[ofs + 12] == 'I') && (buf[ofs + 13] == 'I')) {
    77          d->order = EXIF_BYTE_ORDER_INTEL;
    78      } else {
    79          exif_log(md->log, EXIF_LOG_CODE_CORRUPT_DATA,
    80                  "ExifMnoteDataApple", "Unrecognized byte order");
    81          /*printf("%s(%d)\n", __FUNCTION__, __LINE__);*/
    82          return;
    83      }
    84
    85      tcount = (unsigned int) exif_get_short(buf + ofs + 14, d->order);
    86
    87      /* Sanity check the offset */
    88      if (buf_size < 6 + 16 + tcount * 6 + 4) {
    89          exif_log(md->log, EXIF_LOG_CODE_CORRUPT_DATA,
    90                   "ExifMnoteDataApple", "Short MakerNote");
    91          /*printf("%s(%d)\n", __FUNCTION__, __LINE__);*/
    92          return;
    93      }
    94
    95      /* printf("%s(%d): total %d tags\n", __FUNCTION__, __LINE__, tcount); */
    96
    97      ofs += 16;
    98
    99      exif_mnote_data_apple_free(md);
   100
   101      /* Reserve enough space for all the possible MakerNote tags */
   102      d->entries = exif_mem_alloc(md->mem, sizeof(MnoteAppleEntry) * tcount);
   103      if (!d->entries) {
   104          EXIF_LOG_NO_MEMORY(md->log, "ExifMnoteApple", sizeof(MnoteAppleEntry) * tcount);
   105          /*printf("%s(%d)\n", __FUNCTION__, __LINE__);*/
   106          return;
   107      }
   108
   109      for (i = 0; i < tcount; i++) {
   110          d->entries[i].tag = exif_get_short(buf + ofs, d->order);
   111          d->entries[i].format = exif_get_short(buf + ofs + 2, d->order);
   112          d->entries[i].components = exif_get_long(buf + ofs + 4, d->order);
   113          d->entries[i].order = d->order;
   114          dsize = exif_format_get_size(d->entries[i].format) * d->entries[i].components;
   115          if (dsize > 4) {
   116              dofs = d->offset + exif_get_long(buf + ofs + 8, d->order);
   117          } else {
   118              dofs = ofs + 8;
   119          }
   120          ofs += 12;
   121          d->entries[i].data = exif_mem_alloc(md->mem, dsize);
   122          if (!d->entries[i].data) {
   123              EXIF_LOG_NO_MEMORY(md->log, "ExifMnoteApple", dsize);
   124              continue;
   125          }
   126          memcpy(d->entries[i].data, buf + dofs, dsize);
   127          d->entries[i].size = dsize;
   128      }
   129      d->count = tcount;
   130
   131      return;
   132  }
