   148      unsigned int i;
   149
   150      /*printf("%s\n", __FUNCTION__);*/
   151
   152      if (!d || d->order == o) {
   153          return;
   154      }
   155
   156      for (i = 0; i < d->count; i++) {
   157          if (d->entries[i].size != (exif_format_get_size(d->entries[i].format) * d->entries[i].components)) {
   158              continue;
   159          }
