   305  char *
   306  mnote_apple_entry_get_value(MnoteAppleEntry *entry, char *v, unsigned int maxlen) {
   307      ExifSLong vsl = 0;
   308
   309      if (!entry)
   310          return NULL;
   311
   312      memset(v, 0, maxlen);
   313      maxlen--;
   314
   315      switch (entry->tag) {
   316      case MNOTE_APPLE_TAG_HDR:
   317          vsl = exif_get_slong(entry->data, entry->order);
   318          snprintf(v, maxlen, "%d", vsl);
   319          break;
   320      default:
   321          snprintf(v, maxlen, "total %u unsupported data", entry->size);
   322          break;
   323      }
   324
   325      return v;
   326  }
